Step 1 : manifest.json
JSON
{
  "manifest_version": 3,

  "name": "ChatGPT Extractor",

  "description": "Extract ChatGPT conversation",

  "version": "1.0",

  "permissions": [
    "storage",
    "activeTab",
    "scripting"
  ],

  "host_permissions": [
    "https://chatgpt.com/*"
  ],

  "background": {
    "service_worker": "background.js"
  },

  "action": {
    "default_popup": "popup.html"
  },

  "content_scripts": [
    {
      "matches": [
        "https://chatgpt.com/*"
      ],
      "js": [
        "utils/parser.js",
        "content.js"
      ],
      "run_at": "document_idle"
    }
  ]
}
