popup.js
JavaScript
document.getElementById("extract").onclick = async ()=>{

let [tab]=await chrome.tabs.query({
    active:true,
    currentWindow:true
});

chrome.tabs.sendMessage(
tab.id,
{
action:"extract"
},
(res)=>{

document.getElementById("result").textContent=
JSON.stringify(res,null,2);

});

};
