utils/parser.js

This file only contains parsing logic.

JavaScript
class ChatParser{

static getConversationId(){

let arr=location.pathname.split("/");

return arr[arr.length-1];

}

static getMessages(){

let msgs=[];

document
.querySelectorAll("[data-message-author-role]")
.forEach((e)=>{

msgs.push({

role:e.dataset.messageAuthorRole,

text:e.innerText.trim(),

timestamp:new Date().toISOString()

});

});

return msgs;

}

}
content.js
JavaScript
chrome.runtime.onMessage.addListener(

(req,sender,sendResponse)=>{

if(req.action!="extract")
return;

const data={

provider:"OpenAI",

llm:"ChatGPT",

sessionId:ChatParser.getConversationId(),

url:location.href,

title:document.title,

timestamp:new Date().toISOString(),

messages:ChatParser.getMessages()

};

sendResponse(data);

});
